package com.hbm.machine.reactor.rbmk.console;
import com.hbm.api.computer.*;
import com.hbm.api.machine.MachineView;
import com.hbm.fluid.network.FluidUser;
import com.hbm.machine.reactor.rbmk.boiler.RbmkBoilerEntity;
import com.hbm.machine.reactor.rbmk.channel.RbmkFuelChannelEntity;
import com.hbm.machine.reactor.rbmk.column.RbmkColumnEntity;
import com.hbm.machine.reactor.rbmk.control.RbmkControlEntity;
import com.hbm.machine.reactor.rbmk.fuel.RbmkFuelRodItem;
import com.hbm.registry.HbmSounds;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.Mth;
import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import static com.hbm.machine.reactor.rbmk.console.RbmkConsoleData.*;
/** Original15x15 console scan, six aggregate panels, sixty-flux history and seven real OC callbacks. */
public final class RbmkConsoleEntity extends BlockEntity implements RbmkTargetConsole,ComputerControl,MachineView,com.hbm.multiblock.MuffledMachine {
    private BlockPos target=BlockPos.ZERO;private byte rotation;public final Column[] columns=new Column[225];public final Status[] screens=new Status[6];public int[] fluxBuffer=new int[60];public boolean muffled;
    public RbmkConsoleEntity(BlockPos pos,BlockState state){super(RbmkConsoleContent.ENTITY.get(),pos,state);Arrays.setAll(screens,i->new Status());}
    @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
    @Override public void setTarget(BlockPos pos){target=pos.immutable();setChanged();}public void rotate(){rotation=(byte)((rotation+1)%4);setChanged();}
    public int xFromIndex(int index){int i=index%15-7,j=index/15-7;return switch(rotation){case 1->-j;case 2->-i;case 3->j;default->i;};}public int zFromIndex(int index){int i=index%15-7,j=index/15-7;return switch(rotation){case 1->i;case 2->-j;case 3->-i;default->j;};}
    private RbmkColumnEntity column(int dx,int dz){if(level==null)return null;var pos=target.offset(dx,0,dz);return level.hasChunkAt(pos)&&level.getBlockEntity(pos) instanceof RbmkColumnEntity column?column:null;}
    private RbmkColumnEntity column(int index){return column(xFromIndex(index),zFromIndex(index));}
    public static void tick(Level level,BlockPos pos,BlockState state,RbmkConsoleEntity console){if(level instanceof ServerLevel world){boolean full=world.getGameTime()%10==0;if(full){console.rescan();console.prepareScreens();}RbmkConsoleNetwork.sync(world,console,full);}}
    private void rescan(){double flux=0;for(int index=0;index<columns.length;index++){var column=column(index);if(column==null){columns[index]=null;continue;}var type=ColumnType.valueOf(column.consoleType());var tag=column.consoleData();if(tag==null)tag=new CompoundTag();tag.putDouble("heat",column.heat);tag.putDouble("maxHeat",column.maxHeat());tag.putByte("indicator",(byte)column.craneIndicator);if(column.isModerated())tag.putBoolean("moderated",true);columns[index]=new Column(type,tag);if(column instanceof RbmkFuelChannelEntity fuel)flux+=fuel.lastFluxQuantity;}System.arraycopy(fluxBuffer,1,fluxBuffer,0,fluxBuffer.length-1);fluxBuffer[fluxBuffer.length-1]=(int)flux;}
    private void prepareScreens(){for(var screen:screens){if(screen.type==ScreenType.NONE){screen.display=null;continue;}double value=0;int count=0;for(int index:screen.columns){var col=columns[index];if(col==null)continue;var tag=col.data();switch(screen.type){case COL_TEMP->{count++;value+=tag.getDouble("heat");}case FUEL_DEPLETION->{if(tag.contains("enrichment")){count++;value+=100-tag.getDouble("enrichment")*100;}}case FUEL_POISON->{if(tag.contains("xenon")){count++;value+=tag.getDouble("xenon");}}case FUEL_TEMP->{if(tag.contains("c_heat")){count++;value+=tag.getDouble("c_heat");}}case ROD_EXTRACTION->{if(tag.contains("level")){count++;value+=tag.getDouble("level")*100;}}default->{}}}String text=(int)(value/count*10)/10D+"";screen.display=switch(screen.type){case COL_TEMP->"rbmk.screen.temp="+text+"°C";case FUEL_DEPLETION->"rbmk.screen.depletion="+text+"%";case FUEL_POISON->"rbmk.screen.xenon="+text+"%";case FUEL_TEMP->"rbmk.screen.core="+text+"°C";case ROD_EXTRACTION->"rbmk.screen.rod="+text+"%";default->null;};}}
    public boolean hasPermission(Player player){return player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<400;}
    public void receiveControl(CompoundTag data){if(data.contains("level"))for(String key:data.getAllKeys())if(key.startsWith("sel_")){int index=data.getInt(key);if(index>=0&&index<225&&column(index) instanceof RbmkControlEntity rod&&!rod.automatic()){rod.setTarget(Mth.clamp(data.getDouble("level"),0,1));rod.setChanged();}}
        if(data.contains("toggle")){int id=data.getByte("toggle");if(id>=0&&id<6){var screen=screens[id];screen.type=ScreenType.values()[(screen.type.ordinal()+1)%ScreenType.values().length];}}
        if(data.contains("id")){int id=data.getByte("id");if(id>=0&&id<6)screens[id].columns=java.util.stream.IntStream.range(0,225).filter(i->data.getBoolean("s"+i)).toArray();}
        if(data.contains("assignColor")){int color=data.getByte("assignColor");for(int index:data.getIntArray("cols"))if(index>=0&&index<225&&column(index) instanceof RbmkControlEntity rod&&!rod.automatic()){rod.color=RbmkControlEntity.Color.values()[Mth.clamp(color,0,4)];rod.setChanged();}}
        if(data.contains("compressor"))for(int index:data.getIntArray("cols"))if(index>=0&&index<225&&column(index) instanceof RbmkBoilerEntity boiler)boiler.cycleCompressor();setChanged();
    }
    public CompoundTag syncData(boolean full){var tag=new CompoundTag();tag.putBoolean("full",full);tag.putBoolean("muffled",muffled);for(int i=0;i<6;i++)tag.putByte("screenType"+i,(byte)screens[i].type.ordinal());if(full){for(int i=0;i<225;i++)if(columns[i]!=null){var value=new CompoundTag();value.putByte("type",(byte)columns[i].type().ordinal());value.put("data",columns[i].data());tag.put("col"+i,value);}tag.putIntArray("flux",fluxBuffer);for(int i=0;i<6;i++)if(screens[i].display!=null)tag.putString("display"+i,screens[i].display);}return tag;}
    public void sync(CompoundTag tag){muffled=tag.getBoolean("muffled");for(int i=0;i<6;i++)screens[i].type=ScreenType.values()[Mth.clamp(tag.getByte("screenType"+i),0,5)];if(tag.getBoolean("full")){for(int i=0;i<225;i++){var value=tag.getCompound("col"+i);columns[i]=tag.contains("col"+i)?new Column(ColumnType.values()[Mth.clamp(value.getByte("type"),0,13)],value.getCompound("data")):null;}int[] history=tag.getIntArray("flux");if(history.length==60)fluxBuffer=history;for(int i=0;i<6;i++)screens[i].display=tag.contains("display"+i)?tag.getString("display"+i):null;}}
    @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.putBoolean("muffled",muffled);tag.putInt("tX",target.getX());tag.putInt("tY",target.getY());tag.putInt("tZ",target.getZ());tag.putByte("rotation",rotation);for(int i=0;i<6;i++){tag.putByte("t"+i,(byte)screens[i].type.ordinal());tag.putIntArray("s"+i,screens[i].columns);}}
    @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);muffled=tag.getBoolean("muffled");target=new BlockPos(tag.getInt("tX"),tag.getInt("tY"),tag.getInt("tZ"));rotation=(byte)Math.floorMod(tag.getByte("rotation"),4);for(int i=0;i<6;i++){screens[i].type=ScreenType.values()[Mth.clamp(tag.getByte("t"+i),0,5)];screens[i].columns=Arrays.stream(tag.getIntArray("s"+i)).filter(n->n>=0&&n<225).toArray();}}
    @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){return syncData(true);}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){sync(tag);}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
    @Override public String computerType(){return "rbmk_console";}@Override public String[] computerMethods(){return new String[]{"getColumnData","getRBMKPos","setLevel","setColumnLevel","setColorLevel","setColor","pressAZ5"};}
    private String legacy(ItemStack stack){return "item."+BuiltInRegistries.ITEM.getKey(stack.getItem()).getPath();}
    private Object[] columnData(ComputerArguments args)throws ComputerException{int x=args.checkInteger(0)-7,z=-args.checkInteger(1)+7,i=x,j=z;switch(rotation){case 1->{i=z;j=-x;}case 2->{i=-x;j=-z;}case 3->{i=-z;j=x;}}int index=(j+7)*15+i+7;if(index<0||index>=225)throw new ComputerException("Column coordinates outside0..14");var column=column(x,z);if(column==null)return new Object[]{null};if(columns[index]==null)throw new ComputerException("Column data is not scanned yet");var tag=columns[index].data();var data=new LinkedHashMap<String,Object>();data.put("type",column.consoleType());data.put("hullTemp",tag.getDouble("heat"));data.put("realSimWater",column.reasimWater);data.put("realSimSteam",column.reasimSteam);data.put("moderated",tag.getBoolean("moderated"));data.put("level",tag.getDouble("level"));data.put("targetLevel",tag.getDouble("targetLevel"));data.put("color",tag.getShort("color"));data.put("enrichment",tag.getDouble("enrichment"));data.put("xenon",tag.getDouble("xenon"));data.put("coreSkinTemp",tag.getDouble("c_heat"));data.put("coreTemp",tag.getDouble("c_coreHeat"));data.put("coreMaxTemp",tag.getDouble("c_maxHeat"));
        if(column instanceof RbmkControlEntity control&&control.automatic()){data.put("function",control.function.toString());data.put("heatUpper",control.heatUpper);data.put("heatLower",control.heatLower);data.put("levelUpper",control.levelUpper);data.put("levelLower",control.levelLower);}
        if(column instanceof RbmkFuelChannelEntity fuel){data.put("fluxQuantity",fuel.lastFluxQuantity);data.put("fluxRatio",fuel.fluxFastRatio);data.put("rodName",fuel.getItem(0).isEmpty()?"":legacy(fuel.getItem(0)));}
        if(column instanceof RbmkBoilerEntity boiler){data.put("water",boiler.feed.getFill());data.put("steam",boiler.steam.getFill());data.put("steamType",com.hbm.fluid.HbmFluids.fromID(tag.getShort("type")).getUnlocalizedName());}
        if(column.consoleType().equals("HEATEX")&&column instanceof FluidUser fluid){var tanks=fluid.getAllTanks();data.put("coolant",tanks[0].getFill());data.put("hotcoolant",tanks[1].getFill());data.put("coldtype",com.hbm.fluid.HbmFluids.fromID(tag.getShort("type")).getUnlocalizedName());data.put("hottype",com.hbm.fluid.HbmFluids.fromID(tag.getShort("hottype")).getUnlocalizedName());}
        if(column.consoleType().equals("COOLER")&&column instanceof FluidUser fluid)data.put("cryogel",fluid.getAllTanks()[0].getFill());
        if(column.consoleType().equals("STORAGE")&&column instanceof Container inventory)for(int slot=0;slot<12;slot++){var stack=inventory.getItem(slot);if(stack.getItem() instanceof RbmkFuelRodItem){data.put("slot"+slot+"coreSkinTemp",RbmkFuelRodItem.getHullHeat(stack));data.put("slot"+slot+"coreTemp",RbmkFuelRodItem.getCoreHeat(stack));data.put("slot"+slot+"enrichment",RbmkFuelRodItem.getEnrichment(stack));data.put("slot"+slot+"xenon",RbmkFuelRodItem.getPoison(stack));data.put("slot"+slot+"rodName",legacy(stack));}}
        if(column instanceof RbmkConsoleExtra extra)extra.consoleComputerData(data);return new Object[]{data};
    }
    private boolean setLevels(double value,Integer color){boolean found=false;for(int x=-7;x<=7;x++)for(int z=-7;z<=7;z++)if(column(x,z) instanceof RbmkControlEntity rod&&!rod.automatic()&&(color==null||rod.color==RbmkControlEntity.Color.values()[color])){rod.setTarget(Mth.clamp(value,0,1));rod.setChanged();found=true;}return found;}
    @Override public Object[] callComputer(String method,ComputerArguments args)throws ComputerException{return switch(method){case "getColumnData"->columnData(args);case "getRBMKPos"->{if(target.equals(BlockPos.ZERO))yield new Object[]{null};var data=new LinkedHashMap<String,Integer>();data.put("rbmkCenterX",target.getX());data.put("rbmkCenterY",target.getY());data.put("rbmkCenterZ",target.getZ());yield new Object[]{data};}case "setLevel"->setLevels(args.checkDouble(0),null)?new Object[]{}:new Object[]{"No control rods found"};case "setColumnLevel"->{int x=args.checkInteger(0)-7,z=-args.checkInteger(1)+7;double value=args.checkDouble(2);if(column(x,z) instanceof RbmkControlEntity rod&&!rod.automatic()){rod.setTarget(Mth.clamp(value,0,1));rod.setChanged();yield new Object[]{};}yield new Object[]{"No control rod found at "+(x+7)+","+(7-z)};}case "setColorLevel"->{int color=args.checkInteger(0);double value=args.checkDouble(1);yield color<0||color>4?new Object[]{"Color "+color+" does not exist"}:setLevels(value,color)?new Object[]{}:new Object[]{"No rods for color "+color+" found"};}case "setColor"->{int x=args.checkInteger(0)-7,z=-args.checkInteger(1)+7,color=args.checkInteger(2);if(color<0||color>4)yield new Object[]{"Color "+color+" does not exist"};if(column(x,z) instanceof RbmkControlEntity rod&&!rod.automatic()){rod.color=RbmkControlEntity.Color.values()[color];rod.setChanged();yield new Object[]{};}yield new Object[]{"No control rod found at "+(x+7)+","+(7-z)};}case "pressAZ5"->{level.playSound(null,worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5,HbmSounds.get("block.shutdown"),SoundSource.BLOCKS,1,1);yield setLevels(0,null)?new Object[]{}:new Object[]{"No control rods found"};}default->throw new ComputerException("No such method: "+method);};}
    @Override public long energyStored(){return 0;}@Override public long energyCapacity(){return 0;}
}
